inline std::vector<unsigned char> mark_bytes(const char* p){std::vector<unsigned char> out;auto digit=[](char c){return c<='9'?c-'0':c-'a'+10;};for(;*p;p+=2)out.push_back(static_cast<unsigned char>(digit(p[0])*16+digit(p[1])));return out;}
inline std::vector<double> doubles(const char* p){auto raw=mark_bytes(p);std::vector<double> out(raw.size()/8);std::memcpy(out.data(),raw.data(),raw.size());return out;}
